# vlpt on Sing-box (private module, vlpt dual-support).
# Inserted into installsb() before the sspt block. Only runs when vlpt is
# selected AND vlpt_on=sb (computed at the top of ins() from vlpt_kernel
# and the other selected protocols). Otherwise it leaves vlp untouched:
# if vlpt is selected but vlpt_on=xray, installxray() will install it;
# if vlpt is not selected at all, the else branch sets vlp=vlptargo
# (the recovery dummy, same as every other protocol block).
# Reality keypair: generated exactly like the arpt block (sbk dir, reuse
# if it already exists, so arpt + vlpt-sb share one keypair and one
# pbk/sid pair). ym_vl_re defaults to apple.com, same as arpt/xray.
if [ -n "$vlp" ] && [ "$vlpt_on" = "sb" ]; then
vlp=vlpt
if [ -z "$ym_vl_re" ]; then ym_vl_re=apple.com; fi
echo "$ym_vl_re" > "$HOME/agsbx/ym_vl_re"
echo "Reality域名：$ym_vl_re"
mkdir -p "$HOME/agsbx/sbk"
if [ ! -e "$HOME/agsbx/sbk/private_key" ]; then
key_pair=$("$HOME/agsbx/sing-box" generate reality-keypair)
private_key=$(echo "$key_pair" | awk '/PrivateKey/ {print $2}' | tr -d '"')
public_key=$(echo "$key_pair" | awk '/PublicKey/ {print $2}' | tr -d '"')
short_id=$("$HOME/agsbx/sing-box" generate rand --hex 4)
echo "$private_key" > "$HOME/agsbx/sbk/private_key"
echo "$public_key" > "$HOME/agsbx/sbk/public_key"
echo "$short_id" > "$HOME/agsbx/sbk/short_id"
fi
private_key_s=$(cat "$HOME/agsbx/sbk/private_key")
public_key_s=$(cat "$HOME/agsbx/sbk/public_key")
short_id_s=$(cat "$HOME/agsbx/sbk/short_id")
if [ -z "$port_vl_re" ] && [ ! -e "$HOME/agsbx/port_vl_re" ]; then
port_vl_re=$(shuf -i 10000-65535 -n 1)
echo "$port_vl_re" > "$HOME/agsbx/port_vl_re"
elif [ -n "$port_vl_re" ]; then
echo "$port_vl_re" > "$HOME/agsbx/port_vl_re"
fi
port_vl_re=$(cat "$HOME/agsbx/port_vl_re")
echo "Vless-tcp-reality-v端口（Sing-box）：$port_vl_re"
cat >> "$HOME/agsbx/sb.json" <<EOF
    {
        "type": "vless",
        "tag": "vl-reality-sb",
        "listen": "::",
        "listen_port": ${port_vl_re},
        "users": [
            {
                "uuid": "${uuid}",
                "flow": "xtls-rprx-vision"
            }
        ],
        "tls": {
            "enabled": true,
            "server_name": "${ym_vl_re}",
            "reality": {
                "enabled": true,
                "handshake": {
                    "server": "${ym_vl_re}",
                    "server_port": 443
                },
                "private_key": "$private_key_s",
                "short_id": ["$short_id_s"]
            }
        }
    },
EOF
else
[ -n "$vlp" ] || vlp=vlptargo
fi
# vlpt2 on Sing-box (private module, second vlpt instance).
# Inserted into installsb() after the vlpt-sb block, before sspt.
# Only runs when vlpt2 is selected AND vlpt_on=sb (shared with vlpt).
# Shares vlpt's Sing-box Reality keypair (sbk, also shared with arpt),
# so pbk/sid are the same as vlpt's; only port, tag and display
# name differ. If vlpt2 is not selected, vlp2 becomes vlpt2argo.
if [ -n "$vlp2" ] && [ "$vlpt_on" = "sb" ]; then
vlp2=vlpt2
if [ -z "$ym_vl_re" ]; then ym_vl_re=apple.com; fi
echo "$ym_vl_re" > "$HOME/agsbx/ym_vl_re"
echo "Reality域名：$ym_vl_re"
mkdir -p "$HOME/agsbx/sbk"
if [ ! -e "$HOME/agsbx/sbk/private_key" ]; then
key_pair=$("$HOME/agsbx/sing-box" generate reality-keypair)
private_key=$(echo "$key_pair" | awk '/PrivateKey/ {print $2}' | tr -d '"')
public_key=$(echo "$key_pair" | awk '/PublicKey/ {print $2}' | tr -d '"')
short_id=$("$HOME/agsbx/sing-box" generate rand --hex 4)
echo "$private_key" > "$HOME/agsbx/sbk/private_key"
echo "$public_key" > "$HOME/agsbx/sbk/public_key"
echo "$short_id" > "$HOME/agsbx/sbk/short_id"
fi
private_key_s=$(cat "$HOME/agsbx/sbk/private_key")
public_key_s=$(cat "$HOME/agsbx/sbk/public_key")
short_id_s=$(cat "$HOME/agsbx/sbk/short_id")
if [ -z "$port_vl_re2" ] && [ ! -e "$HOME/agsbx/port_vl_re2" ]; then
port_vl_re2=$(shuf -i 10000-65535 -n 1)
echo "$port_vl_re2" > "$HOME/agsbx/port_vl_re2"
elif [ -n "$port_vl_re2" ]; then
echo "$port_vl_re2" > "$HOME/agsbx/port_vl_re2"
fi
port_vl_re2=$(cat "$HOME/agsbx/port_vl_re2")
echo "Vless-tcp-reality-v2端口（Sing-box）：$port_vl_re2"
cat >> "$HOME/agsbx/sb.json" <<EOF
    {
        "type": "vless",
        "tag": "vl-reality-sb-2",
        "listen": "::",
        "listen_port": ${port_vl_re2},
        "users": [
            {
                "uuid": "${uuid}",
                "flow": "xtls-rprx-vision"
            }
        ],
        "tls": {
            "enabled": true,
            "server_name": "${ym_vl_re}",
            "reality": {
                "enabled": true,
                "handshake": {
                    "server": "${ym_vl_re}",
                    "server_port": 443
                },
                "private_key": "$private_key_s",
                "short_id": ["$short_id_s"]
            }
        }
    },
EOF
else
[ -n "$vlp2" ] || vlp2=vlpt2argo
fi

# vlpt more instances on Sing-box (private module, loop).
# Same vlpt_more list as the Xray block, instances 2, 3, ... in order
# (3, 4, ... if the old vlpt2 variable is also set), sharing vlpt's
# uuid and Sing-box Reality keypair (sbk), with their own port and
# inbound tag vl-reality-sb-2, vl-reality-sb-3, ...
# Only runs when vlpt_on=sb. Generates sbk if missing, like vlpt-sb.
if [ -n "$vlpt_more" ] && [ "$vlpt_on" = "sb" ]; then
if [ -z "$ym_vl_re" ]; then ym_vl_re=apple.com; fi
echo "$ym_vl_re" > "$HOME/agsbx/ym_vl_re"
echo "Reality域名：$ym_vl_re"
mkdir -p "$HOME/agsbx/sbk"
if [ ! -e "$HOME/agsbx/sbk/private_key" ]; then
key_pair=$("$HOME/agsbx/sing-box" generate reality-keypair)
private_key=$(echo "$key_pair" | awk '/PrivateKey/ {print $2}' | tr -d '"')
public_key=$(echo "$key_pair" | awk '/PublicKey/ {print $2}' | tr -d '"')
short_id=$("$HOME/agsbx/sing-box" generate rand --hex 4)
echo "$private_key" > "$HOME/agsbx/sbk/private_key"
echo "$public_key" > "$HOME/agsbx/sbk/public_key"
echo "$short_id" > "$HOME/agsbx/sbk/short_id"
fi
private_key_s=$(cat "$HOME/agsbx/sbk/private_key")
public_key_s=$(cat "$HOME/agsbx/sbk/public_key")
short_id_s=$(cat "$HOME/agsbx/sbk/short_id")
if [ "$vlp2" = yes ] || [ -n "$vlpt2" ]; then _vlpt_more_idx=3; else _vlpt_more_idx=2; fi
_vlpt_more_oldifs="$IFS"; IFS=','
for _vlpt_more_p in $vlpt_more; do
  _vlpt_more_p=$(printf '%s' "$_vlpt_more_p" | xargs 2>/dev/null || printf '%s' "$_vlpt_more_p")
  case "$_vlpt_more_p" in ''|*[!0-9]*) echo "vlpt 更多实例端口格式错误，已跳过：$_vlpt_more_p"; _vlpt_more_idx=$((_vlpt_more_idx + 1)); continue;; esac
  echo "$_vlpt_more_p" > "$HOME/agsbx/port_vl_re$_vlpt_more_idx"
  echo "Vless-tcp-reality-v$_vlpt_more_idx端口（Sing-box）：$_vlpt_more_p"
  cat >> "$HOME/agsbx/sb.json" <<EOF
    {
        "type": "vless",
        "tag": "vl-reality-sb-$_vlpt_more_idx",
        "listen": "::",
        "listen_port": ${_vlpt_more_p},
        "users": [
            {
                "uuid": "${uuid}",
                "flow": "xtls-rprx-vision"
            }
        ],
        "tls": {
            "enabled": true,
            "server_name": "${ym_vl_re}",
            "reality": {
                "enabled": true,
                "handshake": {
                    "server": "${ym_vl_re}",
                    "server_port": 443
                },
                "private_key": "$private_key_s",
                "short_id": ["$short_id_s"]
            }
        }
    },
EOF
  _vlpt_more_idx=$((_vlpt_more_idx + 1))
done; IFS="$_vlpt_more_oldifs"
fi

if [ -n "$ssp" ]; then
ssp=sspt
if [ ! -e "$HOME/agsbx/sskey" ]; then
sskey=$("$HOME/agsbx/sing-box" generate rand 16 --base64)
echo "$sskey" > "$HOME/agsbx/sskey"
fi
if [ -z "$port_ss" ] && [ ! -e "$HOME/agsbx/port_ss" ]; then
port_ss=$(shuf -i 10000-65535 -n 1)
echo "$port_ss" > "$HOME/agsbx/port_ss"
elif [ -n "$port_ss" ]; then
echo "$port_ss" > "$HOME/agsbx/port_ss"
fi
sskey=$(cat "$HOME/agsbx/sskey")
port_ss=$(cat "$HOME/agsbx/port_ss")
echo "Shadowsocks-2022端口：$port_ss"
cat >> "$HOME/agsbx/sb.json" <<EOF
        {
            "type": "shadowsocks",
            "tag":"ss-2022",
            "listen": "::",
            "listen_port": $port_ss,
            "method": "2022-blake3-aes-128-gcm",
            "password": "$sskey"
    },  
EOF
else
ssp=ssptargo
fi
}

